package io.hydrox.quickprayerpreview;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(QuickPrayerPreviewPlugin.CONFIG_GROUP)
public interface QuickPrayerPreviewConfig extends Config
{
	@ConfigItem(
		keyName = "tooltipPosition",
		name = "Tooltip Position",
		description = "Where to place the preview tooltip"
	)
	default TooltipPosition tooltipPosition() { return TooltipPosition.OPPOSITE; }

	enum TooltipPosition
	{
		OPPOSITE,
		WITH_OTHERS
	}
}

